CREATE TABLE notification_templates(template_key varchar(80) NOT NULL,language varchar(8) NOT NULL CHECK(language IN ('en','ta')),subject varchar(300) NOT NULL,body text NOT NULL,optional boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(template_key,language));
CREATE TABLE notification_requests(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid,customer_id uuid NOT NULL,channel varchar(16) NOT NULL CHECK(channel IN ('EMAIL','SMS','WHATSAPP')),template_key varchar(80) NOT NULL,language varchar(8) NOT NULL,source_event_id uuid NOT NULL,related_resource_id uuid NOT NULL,source_envelope jsonb NOT NULL,encrypted_recipient text,encrypted_content text,status varchar(20) NOT NULL CHECK(status IN ('PENDING','APPROVED','QUEUED','SENDING','SENT','FAILED','CANCELLED')),attempt_count int NOT NULL DEFAULT 0,provider_message_id varchar(200),provider_status varchar(40),next_attempt_at timestamptz NOT NULL DEFAULT now(),claim_token uuid,lease_until timestamptz,sent_at timestamptz,failed_at timestamptz,last_error varchar(80),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,source_event_id,channel,template_key));
CREATE INDEX notification_branch_history ON notification_requests(tenant_id,branch_id,created_at DESC,id);
CREATE INDEX notification_due ON notification_requests(next_attempt_at) WHERE status IN ('APPROVED','QUEUED','SENDING');
CREATE TABLE notification_attempts(id uuid PRIMARY KEY,notification_id uuid NOT NULL REFERENCES notification_requests(id),attempt_number int NOT NULL,category varchar(80) NOT NULL,provider_message_id varchar(200),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(notification_id,attempt_number));
CREATE TABLE notification_audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,notification_id uuid,actor_id uuid,action varchar(80) NOT NULL,reason varchar(500),correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_delivery_receipts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,notification_id uuid NOT NULL REFERENCES notification_requests(id),provider_receipt_id varchar(200) NOT NULL UNIQUE,status varchar(40) NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scheduled_notifications(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid,customer_id uuid NOT NULL,related_resource_id uuid NOT NULL,source_event_id uuid NOT NULL,source_envelope jsonb NOT NULL,template_key varchar(80) NOT NULL,due_at timestamptz NOT NULL,status varchar(20) NOT NULL CHECK(status IN ('SCHEDULED','QUEUED','CANCELLED')),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,related_resource_id,template_key,source_event_id));
CREATE INDEX reminders_due ON scheduled_notifications(due_at) WHERE status='SCHEDULED';
